// MonitorStudyProgressPage.js
import React, { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import {
    PieChart,
    Pie,
    Cell,
    BarChart,
    Bar,
    XAxis,
    YAxis,
    Tooltip,
    ResponsiveContainer,
    Legend,
} from "recharts";

/* ----------------------------------------------------
   PARTICLES (MyStudiesPage / ManageEvaluationTasksPage ile aynı stil)
----------------------------------------------------- */
function FloatingParticles() {
    const [particles, setParticles] = useState([]);

    useEffect(() => {
        const generated = [...Array(55)].map(() => ({
            id: crypto.randomUUID(),
            left: Math.random() * 100,
            top: Math.random() * 100,
            delay: -(Math.random() * 15).toFixed(2),
            duration: 16 + Math.random() * 10,
        }));
        setParticles(generated);
    }, []);

    return (
        <div style={styles.particles}>
            {particles.map((p) => (
                <div
                    key={p.id}
                    style={{
                        ...styles.particle,
                        left: `${p.left}%`,
                        top: `${p.top}vh`,
                        animationDelay: `${p.delay}s`,
                        animationDuration: `${p.duration}s`,
                    }}
                />
            ))}
        </div>
    );
}

/* ----------------------------------------------------
   MAIN PAGE COMPONENT
----------------------------------------------------- */
export default function MonitorStudyProgressPage() {
    const { studyId } = useParams();
    const navigate = useNavigate();

    const [overview, setOverview] = useState(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);

    /* ---------------------- TOAST SYSTEM ---------------------- */
    const [toasts, setToasts] = useState([]);

    const showToast = (msg, type = "error") => {
        const id = crypto.randomUUID();
        setToasts((prev) => [...prev, { id, msg, type }]);
        setTimeout(() => {
            setToasts((prev) => prev.filter((t) => t.id !== id));
        }, 3500);
    };

    /* ---------------------- PDF EXPORT ------------------------- */
    const handleExportPDF = () => {
        alert("PDF export starting… (implement backend)");
    };

    /* ============================================================
       FETCH STUDY PROGRESS DATA
    ============================================================= */
    useEffect(() => {
        const fetchProgress = async () => {
            try {
                setLoading(true);

                const res = await fetch(
                    `http://localhost:8080/api/monitor/${studyId}/progress`,
                    {
                        headers: {
                            Authorization: `Bearer ${localStorage.getItem("token")}`,
                        },
                    }
                );

                if (!res.ok) {
                    throw new Error("Failed to fetch study progress");
                }

                const data = await res.json();
                setOverview(data);
            } catch (e) {
                console.error(e);
                setError(e.message || "Unknown error");
            } finally {
                setLoading(false);
            }
        };

        fetchProgress();
    }, [studyId]);

    /* ============================================================
       HELPERS
    ============================================================= */
    const computeTaskCompletion = (task) => {
        if (!task || !task.totalParticipants) return 0;
        return Math.round((task.completedCount / task.totalParticipants) * 100);
    };

    const computeOverallCompletion = () => {
        if (!overview || !overview.taskStats) return 0;
        const list = overview.taskStats;
        const sum = list.reduce((acc, t) => acc + computeTaskCompletion(t), 0);
        return Math.round(sum / list.length);
    };

    const computeDaysLeft = () => {
        if (!overview || !overview.endDate) return null;
        const now = new Date();
        const end = new Date(overview.endDate);
        const diffMs = end - now;
        return Math.ceil(diffMs / (1000 * 60 * 60 * 24));
    };

    const daysLeft = computeDaysLeft();
    const overallCompletion = computeOverallCompletion();

    /* ============================================================
       RENDER
    ============================================================= */
    return (
        <div style={styles.container}>
            <FloatingParticles />

            {/* ---------- TOAST NOTIFICATIONS ---------- */}
            <div style={styles.toastContainer}>
                {toasts.map((t) => (
                    <div
                        key={t.id}
                        style={{
                            ...styles.toast,
                            background:
                                t.type === "error"
                                    ? "rgba(239,68,68,0.9)"
                                    : "rgba(34,197,94,0.9)",
                        }}
                    >
                        {t.msg}
                    </div>
                ))}
            </div>

            {/* NAVBAR */}
            <div style={styles.navbar}>
                <h2 style={styles.navTitle}>
                    Monitor Progress — {overview?.studyTitle || `Study #${studyId}`}
                </h2>

                <div style={{ display: "flex", gap: "12px" }}>
                    {/* PDF EXPORT BUTTON */}
                    <button
                        style={{
                            ...styles.exportButton,
                            opacity:
                                overview?.status === "COMPLETED" ||
                                overview?.status === "ARCHIVED"
                                    ? 1
                                    : 0.4,
                            cursor:
                                overview?.status === "COMPLETED" ||
                                overview?.status === "ARCHIVED"
                                    ? "pointer"
                                    : "not-allowed",
                        }}

                        // 🔥 HOVER BURAYA EKLENECEK
                        onMouseEnter={(e) => {
                            if (
                                overview?.status === "COMPLETED" ||
                                overview?.status === "ARCHIVED"
                            ) {
                                e.currentTarget.style.transform = "scale(1.06)";
                                e.currentTarget.style.boxShadow =
                                    "0 0 20px rgba(34,197,94,0.55)";
                            }
                        }}

                        onMouseLeave={(e) => {
                            if (
                                overview?.status === "COMPLETED" ||
                                overview?.status === "ARCHIVED"
                            ) {
                                e.currentTarget.style.transform = "scale(1)";
                                e.currentTarget.style.boxShadow =
                                    "0 0 14px rgba(34,197,94,0.35)";
                            }
                        }}

                        onClick={() => {
                            if (
                                overview?.status !== "COMPLETED" &&
                                overview?.status !== "ARCHIVED"
                            ) {
                                showToast(
                                    "📄 Cannot export PDF yet! Study must be COMPLETED or ARCHIVED.",
                                    "error"
                                );
                                return;
                            }
                            handleExportPDF();
                        }}
                    >
                        📄 Export Study Result as PDF
                    </button>


                    <button
                        style={styles.backButton}
                        onMouseEnter={(e) => {
                            e.currentTarget.style.transform = "scale(1.05)";
                            e.currentTarget.style.boxShadow = "0 0 20px rgba(220,38,38,0.7)";
                        }}
                        onMouseLeave={(e) => {
                            e.currentTarget.style.transform = "scale(1)";
                            e.currentTarget.style.boxShadow = "0 0 12px rgba(220,38,38,0.45)";
                        }}

                        onClick={() => navigate(`/manage-tasks/${studyId}`)}
                    >
                        ← Back to Tasks
                    </button>
                </div>
            </div>

            {/* CONTENT */}
            <div style={styles.centerWrapper}>
                {/* OVERALL SUMMARY CARD */}
                <div style={styles.overallCard}>
                    <div style={styles.overallHeaderRow}>
                        <div>
                            <h3 style={styles.overallTitle}>Study Overview</h3>
                            <p style={styles.overallSubtitle}>
                                High-level completion across all evaluation tasks.
                            </p>
                        </div>

                        <div style={styles.overallStatsRight}>
                            <div style={styles.overallStatPill}>
                                👥 {overview?.totalParticipants ?? 0} participants
                            </div>
                            <div style={styles.overallStatPill}>
                                🧩 {overview?.taskStats?.length ?? 0} tasks
                            </div>
                        </div>
                    </div>

                    {/* PROGRESS BAR */}
                    <div style={styles.overallProgressSection}>
                        <div style={styles.progressBackground}>
                            <div
                                style={{
                                    ...styles.progressFill,
                                    width: `${overallCompletion}%`,
                                }}
                            />
                        </div>

                        <div style={styles.overallProgressBottom}>
                            <span style={styles.overallProgressLabel}>
                                Overall completion:{" "}
                                <b>{overallCompletion}%</b>
                            </span>

                            {daysLeft != null && (
                                <span
                                    style={{
                                        ...styles.overallDeadline,
                                        color:
                                            daysLeft < 0
                                                ? "#f87171"
                                                : daysLeft <= 3
                                                    ? "#fde68a"
                                                    : "#6ee7b7",
                                    }}
                                >
                                    ⏱{" "}
                                    {daysLeft < 0
                                        ? "Study ended"
                                        : daysLeft === 0
                                            ? "Ends today"
                                            : `Ends in ${daysLeft} day${
                                                daysLeft === 1 ? "" : "s"
                                            }`}
                                </span>
                            )}
                        </div>
                    </div>
                </div>

                {/* TASK CARDS */}
                <div style={styles.content}>
                    {loading ? (
                        <p style={styles.loading}>Loading progress...</p>
                    ) : error ? (
                        <p style={styles.errorText}>{error}</p>
                    ) : !overview?.taskStats ||
                    overview.taskStats.length === 0 ? (
                        <p style={styles.empty}>No tasks found.</p>
                    ) : (
                        <div style={styles.taskGrid}>
                            {overview.taskStats.map((task) => {
                                const completion = computeTaskCompletion(task);

                                const correct = task.correctCount || 0;
                                const wrong = task.wrongCount || 0;
                                const pending = task.pendingCount || 0;

                                const totalPie = correct + wrong + pending;

                                const pieData =
                                    totalPie === 0
                                        ? [{ name: "Pending", value: 1 }]
                                        : [
                                            { name: "Correct", value: correct },
                                            { name: "Wrong", value: wrong },
                                            { name: "Pending", value: pending },
                                        ];

                                const barData = [
                                    {
                                        name: "Answers",
                                        Correct: correct,
                                        Wrong: wrong,
                                        Pending: pending,
                                    },
                                ];

                                const COLORS = {
                                    correct: "#072588",
                                    wrong: "#f8d548",
                                    pending: "#fafafa",
                                };

                                return (
                                    <div
                                        key={task.taskId}
                                        style={styles.taskCard}
                                        onMouseEnter={(e) => {
                                            e.currentTarget.style.transform =
                                                "translateY(-4px)";
                                            e.currentTarget.style.boxShadow =
                                                "0 12px 28px rgba(0,0,0,0.3)";
                                        }}
                                        onMouseLeave={(e) => {
                                            e.currentTarget.style.transform =
                                                "translateY(0)";
                                            e.currentTarget.style.boxShadow =
                                                "0 0 12px rgba(0,0,0,0.20)";
                                        }}
                                    >
                                        <h3 style={styles.taskTitle}>
                                            #{task.taskId} – {task.questionText}
                                        </h3>

                                        {/* SMALL PROGRESS */}
                                        <div style={styles.taskMetaRow}>
                                            <div style={{ flex: 1 }}>
                                                <div style={styles.progressBackgroundSmall}>
                                                    <div
                                                        style={{
                                                            ...styles.progressFillSmall,
                                                            width: `${completion}%`,
                                                        }}
                                                    />
                                                </div>
                                                <div style={styles.taskProgressInfoRow}>
                                                    <span style={styles.progressLabel}>
                                                        {completion}% completed
                                                    </span>
                                                    <span style={styles.participantLabel}>
                                                        👥 {task.completedCount}/
                                                        {task.totalParticipants}
                                                    </span>
                                                </div>
                                            </div>
                                        </div>

                                        {/* CHARTS */}
                                        <div style={styles.chartsRow}>
                                            {/* PIE CHART */}
                                            <div style={styles.chartBox}>
                                                <h4 style={styles.chartTitle}>Distribution</h4>

                                                <div style={styles.chartInner}>
                                                    <ResponsiveContainer width="100%" height={140}>
                                                        <PieChart>
                                                            <Pie
                                                                data={pieData}
                                                                dataKey="value"
                                                                nameKey="name"
                                                                cx="50%"
                                                                cy="50%"
                                                                outerRadius={45}
                                                                innerRadius={25}
                                                            >
                                                                {pieData.map((entry, i) => (
                                                                    <Cell
                                                                        key={i}
                                                                        fill={
                                                                            entry.name === "Correct"
                                                                                ? COLORS.correct
                                                                                : entry.name === "Wrong"
                                                                                    ? COLORS.wrong
                                                                                    : COLORS.pending
                                                                        }
                                                                        stroke="rgba(15,23,42,0.92)"   // kart arka planı
                                                                        strokeWidth={1}
                                                                    />
                                                                ))}

                                                            </Pie>
                                                            <Tooltip
                                                                contentStyle={{
                                                                    background:
                                                                        "rgba(15,23,42,0.85)",
                                                                    borderRadius: 10,
                                                                    border:
                                                                        "1px solid rgba(255,255,255,0.15)",
                                                                }}
                                                                itemStyle={{
                                                                    color: "white",
                                                                    fontWeight: 600,
                                                                }}
                                                            />
                                                            <Legend
                                                                verticalAlign="bottom"
                                                                height={20}
                                                                iconType="circle"
                                                                wrapperStyle={{
                                                                    fontSize: "0.75rem",
                                                                    color: "#e5e7eb",
                                                                }}
                                                            />
                                                        </PieChart>
                                                    </ResponsiveContainer>
                                                </div>
                                            </div>

                                            {/* BAR CHART */}
                                            <div style={styles.chartBox}>
                                                <h4 style={styles.chartTitle}>Counts</h4>

                                                <div style={styles.chartInner}>
                                                    <ResponsiveContainer width="100%" height={140}>
                                                        <BarChart data={barData}>
                                                            <XAxis
                                                                dataKey="name"
                                                                tick={{ fontSize: 10, fill: "#9ca3af" }}
                                                            />
                                                            <YAxis
                                                                tick={{ fontSize: 10, fill: "#9ca3af" }}
                                                                allowDecimals={false}
                                                            />

                                                            <Tooltip
                                                                contentStyle={{
                                                                    background:
                                                                        "rgba(15,23,42,0.85)",
                                                                    borderRadius: 10,
                                                                    border:
                                                                        "1px solid rgba(255,255,255,0.15)",
                                                                }}
                                                                itemStyle={{
                                                                    color: "white",
                                                                    fontWeight: 600,
                                                                }}
                                                            />

                                                            <Bar
                                                                dataKey="Correct"
                                                                stackId="a"
                                                                fill={COLORS.correct}
                                                            />
                                                            <Bar
                                                                dataKey="Wrong"
                                                                stackId="a"
                                                                fill={COLORS.wrong}
                                                            />
                                                            <Bar
                                                                dataKey="Pending"
                                                                stackId="a"
                                                                fill={COLORS.pending}
                                                            />
                                                        </BarChart>
                                                    </ResponsiveContainer>
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                );
                            })}
                        </div>
                    )}
                </div>
            </div>

            {/* PARTICLE ANIM */}
            <style>
                {`
                @keyframes floatParticle {
                    0% { transform: translateY(0); opacity: .6; }
                    100% { transform: translateY(-120vh); opacity: 0; }
                }
                `}
            </style>
        </div>
    );
}

/* ----------------------------------------------------
   STYLES
----------------------------------------------------- */
const styles = {
    container: {
        minHeight: "100vh",
        background: "linear-gradient(135deg, #0a0a0a, #16213e)",
        color: "#fff",
        fontFamily: "Inter, sans-serif",
        overflow: "hidden",
        position: "relative",
    },

    /* TOAST */
    toastContainer: {
        position: "fixed",
        top: "30px",
        left: "50%",
        transform: "translateX(-50%)",
        display: "flex",
        flexDirection: "column",
        gap: "12px",
        zIndex: 9999,
        alignItems: "center",
    },


    toast: {
        padding: "12px 22px",
        borderRadius: "12px",
        color: "white",
        fontWeight: 600,
        fontSize: "0.95rem",
        boxShadow: "0 6px 20px rgba(0,0,0,0.25)",
        maxWidth: "90vw",
        textAlign: "center",
    },


    /* PARTICLES */
    particles: {
        position: "fixed",
        top: 0,
        left: 0,
        width: "100%",
        height: "100%",
        pointerEvents: "none",
        zIndex: 0,
    },

    particle: {
        position: "absolute",
        width: "4px",
        height: "4px",
        background: "linear-gradient(135deg, #06b6d4, #8b5cf6)",
        borderRadius: "50%",
        animation: "floatParticle linear infinite",
        opacity: 0.5,
    },

    /* NAVBAR */
    navbar: {
        display: "flex",
        justifyContent: "space-between",
        alignItems: "center",
        padding: "20px 40px",
        background: "rgba(255,255,255,0.03)",
        borderBottom: "1px solid rgba(255,255,255,0.1)",
        zIndex: 10,
    },

    navTitle: {
        fontSize: "1.5rem",
        fontWeight: "700",
        color: "#60a5fa",
    },

    exportButton: {
        background: "linear-gradient(135deg, #3b82f6, #22c55e)",   // mavi → yeşil
        border: "1px solid rgba(255,255,255,0.25)",
        padding: "10px 22px",
        borderRadius: "12px",
        color: "white",
        fontWeight: 700,
        fontSize: "0.9rem",
        cursor: "pointer",
        boxShadow: "0 0 14px rgba(34,197,94,0.35)",
        transition: "0.25s ease",
    },


    backButton: {
        background: "rgba(220,38,38,0.15)",
